-- Additive Student benefit-scheme master for institution-configured concessions.
-- Location references reuse Country, State, Campus and AcademicSession.
-- Existing admission/fee quote APIs will consume this master in later phases.

BEGIN;

CREATE TABLE IF NOT EXISTS skolenza."StudentBenefitSchemeMaster" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "TemplateSourceId" bigint,
    "Code" varchar(60) NOT NULL,
    "Name" varchar(150) NOT NULL,
    "Description" varchar(500),
    "CountryId" integer,
    "StateId" integer,
    "CampusId" bigint,
    "AcademicSessionId" bigint,
    "MinimumDiscountPercent" numeric(5,2) NOT NULL,
    "MaximumDiscountPercent" numeric(5,2) NOT NULL,
    "EligibilityDescription" varchar(1000),
    "EvidenceRequirementId" bigint,
    "DisplayOrder" smallint NOT NULL DEFAULT 0,
    "IsActive" boolean NOT NULL DEFAULT true,
    "IsSystemDefined" boolean NOT NULL DEFAULT false,
    "AddedById" bigint,
    "AddedDateTime" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedById" bigint,
    "UpdatedDateTime" timestamp,
    "IsSoftDeleted" boolean NOT NULL DEFAULT false,
    "SoftDeletedById" bigint,
    "DeletedDateTime" timestamp,
    CONSTRAINT "FK_StudentBenefitSchemeMaster_Institution"
        FOREIGN KEY ("InstitutionId") REFERENCES skolenza."Institution"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentBenefitSchemeMaster_Country"
        FOREIGN KEY ("CountryId") REFERENCES skolenza."Country"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentBenefitSchemeMaster_State"
        FOREIGN KEY ("StateId") REFERENCES skolenza."State"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentBenefitSchemeMaster_Campus"
        FOREIGN KEY ("CampusId") REFERENCES skolenza."Campus"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentBenefitSchemeMaster_AcademicSession"
        FOREIGN KEY ("AcademicSessionId") REFERENCES skolenza."AcademicSessionMaster"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentBenefitSchemeMaster_EvidenceRequirement"
        FOREIGN KEY ("EvidenceRequirementId") REFERENCES skolenza."StudentDocumentRequirementMaster"("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_StudentBenefitSchemeMaster_DiscountBounds"
        CHECK ("MinimumDiscountPercent" >= 0 AND "MaximumDiscountPercent" <= 100 AND
               "MinimumDiscountPercent" <= "MaximumDiscountPercent")
);

ALTER TABLE skolenza."StudentBenefitSchemeMaster"
    DROP CONSTRAINT IF EXISTS "FK_StudentBenefitSchemeMaster_EvidenceRequirement";

ALTER TABLE skolenza."StudentDocumentRequirementMaster"
    ALTER COLUMN "Id" TYPE bigint USING "Id"::bigint,
    ALTER COLUMN "TemplateSourceId" TYPE bigint USING "TemplateSourceId"::bigint;

ALTER TABLE skolenza."StudentBenefitSchemeMaster"
    ALTER COLUMN "Id" TYPE bigint USING "Id"::bigint,
    ALTER COLUMN "TemplateSourceId" TYPE bigint USING "TemplateSourceId"::bigint,
    ALTER COLUMN "EvidenceRequirementId" TYPE bigint USING "EvidenceRequirementId"::bigint;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'FK_StudentBenefitSchemeMaster_EvidenceRequirement'
          AND conrelid = 'skolenza."StudentBenefitSchemeMaster"'::regclass
    ) THEN
        ALTER TABLE skolenza."StudentBenefitSchemeMaster"
            ADD CONSTRAINT "FK_StudentBenefitSchemeMaster_EvidenceRequirement"
            FOREIGN KEY ("EvidenceRequirementId")
            REFERENCES skolenza."StudentDocumentRequirementMaster"("Id") ON DELETE RESTRICT;
    END IF;
END $$;

CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentBenefitSchemeMaster_Institution_Code"
    ON skolenza."StudentBenefitSchemeMaster" ("InstitutionId", upper("Code"))
    WHERE NOT "IsSoftDeleted";

CREATE INDEX IF NOT EXISTS "IX_StudentBenefitSchemeMaster_Location_Session"
    ON skolenza."StudentBenefitSchemeMaster"
       ("InstitutionId", "CountryId", "StateId", "CampusId", "AcademicSessionId", "DisplayOrder")
    WHERE NOT "IsSoftDeleted";

INSERT INTO skolenza."Module"
    ("InstitutionId", "ModuleCode", "ModuleName", "DisplayName", "URLPath", "ParentModuleId", "IsLeafNode",
     "IsModuleDisplayInUI", "IsCommonMenu", "IsActive", "ImageIconWeb", "ImageIconMobile", "ItemPriority",
     "Remark", "AddedById", "AddedDateTime", "ModuleScope")
SELECT NULL, 'STUDENT_ADMISSIONS', 'Student-Admissions', 'Student Admissions', '/app/student-admissions', NULL, TRUE,
       TRUE, FALSE, TRUE, 'bi bi-person-plus', 'person-add', 570,
       'Student admission and benefit-scheme operations.', 1, CURRENT_TIMESTAMP, 1
WHERE NOT EXISTS (SELECT 1 FROM skolenza."Module" WHERE "ModuleCode" = 'STUDENT_ADMISSIONS');

INSERT INTO skolenza."ModuleOperationMapping"
    ("ModuleId", "OperationId", "PageURL", "IconURL", "IsCommonItem", "IsOperational", "Priority", "Remark",
     "IsActive", "AddedById", "AddedDateTime")
SELECT module."Id", operation."Id", module."URLPath", module."ImageIconWeb", FALSE, TRUE,
       CASE lower(btrim(operation."OperationName"))
           WHEN 'view' THEN 10 WHEN 'add' THEN 20 WHEN 'update' THEN 30 WHEN 'delete' THEN 40 ELSE 99 END,
       'Student admissions and benefit scheme API permission.', TRUE, 1, CURRENT_TIMESTAMP
FROM skolenza."Module" module
CROSS JOIN skolenza."Operation" operation
WHERE module."ModuleCode" = 'STUDENT_ADMISSIONS'
  AND lower(btrim(operation."OperationName")) IN ('view', 'add', 'update', 'delete')
  AND operation."IsActive"
  AND NOT EXISTS (
      SELECT 1 FROM skolenza."ModuleOperationMapping" existing
      WHERE existing."ModuleId" = module."Id" AND existing."OperationId" = operation."Id"
  );

COMMIT;
